#include <stdio.h>

int main(void) {
    int n;
    unsigned long long energia = 1;

    if (scanf("%d", &n) != 1) {
        return 1;
    }

    /* Cada par de professores custa 3 unidades. */
    for (int i = 1; i < n / 2; i++) {
        energia *= 3;
    }

    /* Se N for ímpar, sobra um professor, que custa 2. */
    if (n % 2 != 0) {
        energia *= 2;
    }

    printf("%llu\n", energia);
    return 0;
}
